import numpy as np
from scipy.optimize import least_squares
def m1(p,t,x,v):
    w=p[0]; lam=p[7]
    return -p[1]*x - p[2]*v - p[3]*x**3 + np.exp(-lam*t)*(p[4]*np.cos(w*t)+p[5]*np.sin(w*t))+p[6]
def m2(p,t,x,v):
    w=p[0]
    return -p[1]*x - p[2]*v - p[3]*x**3 - p[7]*np.sign(v) + p[4]*np.cos(w*t)+p[5]*np.sin(w*t)+p[6]
def m3(p,t,x,v):
    w=p[0]
    return -p[1]*x - p[2]*v - p[3]*x**3 - p[7]*v*np.abs(v) + p[4]*np.cos(w*t)+p[5]*np.sin(w*t)+p[6]
for m,extra in [(m1,0.05),(m2,0.1),(m3,0.1)]:
    best=None
    for w0 in [0.385,0.39,0.395]:
        try:
            r=least_squares(lambda p: m(p,t,x,v)-dv_dt, [w0,3,2,0,5,6,0,extra])
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    print(m.__name__, best.cost*2/len(t)/np.var(dv_dt), np.round(best.x,4))
